from typing import List

class Solution:
    def numberOfLines(self, widths: List[int], s: str) -> List[int]:
        lines = 1
        cur = 0
        for ch in s:
            w = widths[ord(ch) - ord('a')]
            if cur + w > 100:
                lines += 1
                cur = w
            else:
                cur += w
        return [lines, cur]

class Solution {
public:
    vector<int> numberOfLines(vector<int>& widths, string s) {
        int lines = 1, cur = 0;
        for (char ch : s) {
            int w = widths[ch - 'a'];
            if (cur + w > 100) {
                lines++;
                cur = w;
            } else {
                cur += w;
            }
        }
        return {lines, cur};
    }
};

class Solution {
    public int[] numberOfLines(int[] widths, String s) {
        int lines = 1, cur = 0;
        for (char ch : s.toCharArray()) {
            int w = widths[ch - 'a'];
            if (cur + w > 100) {
                lines++;
                cur = w;
            } else {
                cur += w;
            }
        }
        return new int[]{lines, cur};
    }
}

var numberOfLines = function(widths, s) {
    let lines = 1, cur = 0;
    for (let i = 0; i < s.length; i++) {
        const w = widths[s.charCodeAt(i) - 97];
        if (cur + w > 100) {
            lines++;
            cur = w;
        } else {
            cur += w;
        }
    }
    return [lines, cur];
};
